R = [r for _, _, rs in PARTS for r in rs]
def clean(s): return s.replace("{", "").replace("}", "")
if __name__ == "__main__":
    wc = sum(len(clean(r[1]).split()) for r in R)
    out = ["# INV-012 The Ebola War: script v1 (2026-11-19)", "",
           "Working title: **Congo's Ebola Outbreak Is Out of Control. Here's Who Pays.**", f"Words: {wc} (≈ {wc/136:.1f} min at the narrator's pace)", "",
           "Tags: VERIFIED / REPORTED / CLAIM / ESTIMATE / SCENARIO / ILLUSTRATION. Facts: facts.md. Not medical or financial advice. No gore, no patients on screen.", ""]
    for t, st, rows in PARTS:
        out += [f"## {t} ({st})", ""]
        for c, n, fx, v, osd, tg, sfx in rows:
            out += [f"**{c}** {clean(n)}", f"> Visual: {v}  ", f"> On screen: {osd} · Tag: {tg or '-'} · Facts: {fx or '-'} · SFX: {sfx}", ""]
    p = os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../videos/INV-012-congo-ebola/INV-012-congo-ebola-script-v1.md")
    open(p, "w").write("\n".join(out)); print("words", wc, "rows", len(R))
